import * as THREE from 'three';
import {height} from './server.js';
export function impactEffects(scene,low){const count=low?0:100,mesh=new THREE.InstancedMesh(new THREE.IcosahedronGeometry(.045,0),new THREE.MeshStandardMaterial({color:'#f5d9a0',roughness:.45}),Math.max(1,count));mesh.frustumCulled=false;scene.add(mesh);const items=Array.from({length:count},()=>({life:0})),dummy=new THREE.Object3D();let cursor=0,lastHits=0;return {reset(){lastHits=0;for(const p of items)p.life=0;},update(p,dt,seed){if(p.hits>lastHits&&!low){for(let i=0;i<22;i++){const item=items[cursor++%count],ang=Math.random()*6.28;Object.assign(item,{life:.7+Math.random()*.7,x:p.hitX,y:height(p.hitX,p.hitZ,seed)+.7,z:p.hitZ,vx:Math.cos(ang)*(1+Math.random()*4),vy:2+Math.random()*3,vz:Math.sin(ang)*(1+Math.random()*4),size:.6+Math.random()*1.7});}}lastHits=p.hits;for(let i=0;i<count;i++){const a=items[i];if(a.life>0){a.life-=dt;a.vy-=12*dt;a.x+=a.vx*dt;a.y+=a.vy*dt;a.z+=a.vz*dt;const h=height(a.x,a.z,seed)+.04;if(a.y<h){a.y=h;a.vy=Math.abs(a.vy)*.25;a.vx*=.85;a.vz*=.85;}dummy.position.set(a.x,a.y,a.z);dummy.rotation.set(a.life*5,i,a.life*2);dummy.scale.setScalar(Math.max(0,Math.min(1,a.life*3))*a.size);}else{dummy.position.set(0,-10000,0);dummy.scale.setScalar(0);}dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);}mesh.instanceMatrix.needsUpdate=true;}};}
